#ifdef _WIN32
#include <cstring>
#define NAT_STRCMP _stricmp
#else
#include <strings.h>
#define NAT_STRCMP strcasecmp
#endif

// binary search by name (case-insensitive)
LuaNativeFn luaNativeByName(const char* name, uint64_t* hashOut) {
    size_t lo = 0, hi = LUA_NATIVES_COUNT;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        int c = NAT_STRCMP(name, LUA_NATIVES[mid].name);
        if (c == 0) { if (hashOut) *hashOut = LUA_NATIVES[mid].hash; return LUA_NATIVES[mid].fn; }
        if (c < 0) hi = mid; else lo = mid + 1;
    }
    return nullptr;
}

// binary search by 64-bit hash
LuaNativeFn luaNativeByHash(uint64_t hash) {
    size_t lo = 0, hi = LUA_NATIVES_COUNT;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        uint64_t mh = LUA_NATIVES_BY_HASH[mid].hash;
        if (mh == hash) return LUA_NATIVES_BY_HASH[mid].fn;
        if (hash < mh) hi = mid; else lo = mid + 1;
    }
    return nullptr;
}
